{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Negotiate the general cap against the actual exposure and recovery package."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Reduce thresholds; seek a **tipping basket**, so qualifying claims become recoverable from the first dollar once the basket is exceeded."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek a longer general warranty period, taking account of when issues can realistically emerge."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "separate title, capacity and authority protections, with a cap at least equal to the purchase price, substantially longer survival, and no general basket or de minimis."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Preserve appropriate separate treatment for:"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket public-register and incorporated-by-reference disclosure."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Reject constructive knowledge and automatic attribution of advisers’ knowledge."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require valid written consent, effective for this transaction, with all relevant conditions satisfied."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require effective releases of security, guarantees and relevant claims contemporaneously with completion"
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Allocate the agreed Seller-related cost expressly through payment, a price deduction or retained funding for deferred amounts."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Expand the indemnity to cover the identified ownership/transfer defect and resulting losses, with suitable separate limits and survival."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a targeted indemnity for the pre-completion incident, covering agreed investigation, remediation and third-party exposures to the extent legally recoverable."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Apply interim operating covenants to related commitments in aggregate."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "reject blanket “all Claims” limitations, separate fundamental/tax/specific protections, and narrow disclosure and knowledge defences."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 is relevant evidence, not complete verification."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "seek a dedicated pre-completion tax covenant/indemnity, appropriate exclusions, claim-control provisions and survival aligned with relevant assessment periods plus a notification buffer."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

